import { uuid } from "../../utils/runtime.js";
import { redact } from "../../utils/redaction.js";
/** Owns the durable and in-flight halves of the double-fire guard. */
export class FiringBook {
    store;
    admit;
    redactor;
    inFlightConsumed = new Map();
    constructor(store, admit, redactor = { redact }) {
        this.store = store;
        this.admit = admit;
        this.redactor = redactor;
    }
    hasConsumed(recordId, reaction) {
        if (this.store.hasConsumed(recordId, reaction))
            return true;
        return this.inFlightConsumed.get(recordId)?.has(reaction) ?? false;
    }
    mark(fill) {
        if (fill.marked)
            return;
        this.admit?.(fill.flow);
        fill.marked = true;
        for (const id of fill.whenIds) {
            let reactions = this.inFlightConsumed.get(id);
            if (reactions === undefined) {
                reactions = new Set();
                this.inFlightConsumed.set(id, reactions);
            }
            reactions.add(fill.reaction);
        }
    }
    unmark(fill) {
        if (!fill.marked)
            return;
        fill.marked = false;
        for (const id of fill.whenIds) {
            const reactions = this.inFlightConsumed.get(id);
            if (reactions === undefined)
                continue;
            reactions.delete(fill.reaction);
            if (reactions.size === 0)
                this.inFlightConsumed.delete(id);
        }
    }
    record(fill) {
        try {
            if (fill.marked) {
                this.store.append({
                    kind: "firing",
                    at: Date.now(),
                    firing: {
                        id: uuid(),
                        reaction: fill.reaction,
                        flow: fill.flow,
                        bindings: this.redactor.redact(fill.bindings),
                        consumed: fill.whenIds,
                        produced: fill.produced,
                        at: Date.now(),
                    },
                });
            }
        }
        finally {
            this.unmark(fill);
        }
    }
}
